suppressPackageStartupMessages({library(ggplot2);library(patchwork)})
lineage_colors<-c(Breast='#147F8C',Skin='#D57A52')
view_colors<-c(Proteomics='#247D9E',RNA='#8B70B2',Metabolomics='#C48B37',Lipidomics='#B95D72')
lab_theme<-function(){theme_classic(base_size=12)+theme(panel.grid.minor=element_blank(),panel.grid.major=element_blank(),axis.line=element_line(color='#425b65',linewidth=.4),axis.ticks=element_line(color='#425b65',linewidth=.4),plot.title=element_text(face='bold',size=14,color='#111820',margin=margin(b=10)),plot.subtitle=element_text(color='#607B83',size=10,margin=margin(b=12)),axis.title=element_text(color='#49666F'),axis.text=element_text(color='#526D76'),legend.position='top',legend.title=element_blank(),plot.background=element_rect(fill='white',color=NA),plot.margin=margin(18,18,18,18),strip.text=element_text(face='bold',color='#234653'),strip.background=element_rect(fill='#EDF3F0',color=NA))}
scatter_scores<-function(scores,lab,title,xlab,ylab){d<-data.frame(x=scores[,1],y=scores[,2],group=factor(lab$study$metadata$group,levels=lab$study$levels),cell_line=lab$study$metadata$sample_id);ggplot(d,aes(x,y,color=group,shape=group))+geom_point(size=2.8,alpha=.85)+scale_color_manual(values=setNames(c('#287D9E','#BD683C'),lab$study$levels))+scale_shape_manual(values=c(16,17))+labs(title=title,x=xlab,y=ylab)+lab_theme()}
plot_integration<-function(lab,mofa){p<-lab$joint_pca;e<-100*p$explained;scatter_scores(p$scores,lab,'Joint PCA',sprintf('PC1 (%.1f%%)',e[1]),sprintf('PC2 (%.1f%%)',e[2]))+scatter_scores(mofa$scores,lab,'Multi-view MOFA','Factor 1','Factor 2')+plot_layout(guides='collect')&theme(legend.position='top')}
plot_factor_contributions<-function(mofa){d<-as.data.frame(as.table(mofa$variance_explained));names(d)<-c('view','factor','r2');d$view<-factor(d$view,levels=rev(names(view_colors)));ggplot(d,aes(factor,view))+geom_point(aes(size=pmax(0,r2),fill=view),shape=21,color='white',stroke=1)+geom_text(aes(label=sprintf('%.1f%%',r2*100)),nudge_y=-.34,size=3.3,color='#294C58')+scale_fill_manual(values=view_colors,guide='none')+scale_size_area(max_size=23,limits=c(0,max(.1,d$r2)),labels=scales::percent,guide=guide_legend(override.aes=list(fill='#8D9FA4',color='white')))+scale_y_discrete(expand=expansion(add=.65))+labs(title='Which molecular layer does each factor explain?',subtitle='Observed-entry reconstruction R-squared  |  factor contributions can overlap',x='MOFA factor',y='Molecular view',size='R-squared')+lab_theme()+theme(legend.position='right',panel.grid.major=element_blank())}
plot_sample_factors<-function(lab,mofa){d<-data.frame(sample_id=rep(rownames(mofa$scores),ncol(mofa$scores)),factor=rep(colnames(mofa$scores),each=nrow(mofa$scores)),score=as.numeric(mofa$scores));meta<-lab$study$metadata;d$group<-factor(meta$group[match(d$sample_id,meta$sample_id)],levels=lab$study$levels);ord<-order(d$group[seq_len(nrow(meta))],mofa$scores[,1]);d$sample_id<-factor(d$sample_id,levels=rownames(mofa$scores)[rev(ord)]);ggplot(d,aes(factor,sample_id,fill=score))+geom_tile(color='#FAFCFA',linewidth=.25)+facet_grid(group~.,scales='free_y',space='free_y')+scale_fill_gradient2(low='#287A98',mid='#F8F7EE',high='#D4774A',midpoint=0)+labs(title='Every sample has a factor profile',subtitle='Samples grouped by study label and ordered by Factor 1',x=NULL,y=NULL,fill='Factor score')+lab_theme()+theme(axis.text.y=element_blank(),axis.ticks.y=element_blank(),panel.grid=element_blank(),legend.position='right')}
plot_view_agreement<-function(lab){d<-as.data.frame(as.table(lab$agreement));names(d)<-c('first','second','rho');ggplot(d,aes(first,second,fill=rho))+geom_tile(color='white',linewidth=3,width=.96,height=.96)+geom_text(aes(label=sprintf('%.2f',rho)),size=5,color='#193B49')+scale_fill_gradient2(low='#9B79B9',mid='#F5F5ED',high='#6AB4AE',midpoint=0,limits=c(-1,1))+coord_equal()+labs(title='Do the views agree about sample relationships?',subtitle='Spearman correlation of within-view Euclidean distances  |  descriptive',x=NULL,y=NULL,fill='rho')+lab_theme()+theme(panel.grid=element_blank(),legend.position='right')}
plot_gene_pair<-function(lab,gene=NULL){if(is.null(lab$prepared$Proteomics)||is.null(lab$prepared$RNA))return(NULL);p<-lab$prepared$Proteomics$retained;r<-lab$prepared$RNA$retained;shared<-intersect(colnames(p),colnames(r));if(!length(shared))return(NULL);if(is.null(gene)&&'EPCAM'%in%shared)gene<-'EPCAM';if(is.null(gene)){score<-sapply(shared,function(g)var(p[,g],na.rm=TRUE)*var(r[,g],na.rm=TRUE));gene<-shared[which.max(score)]};d<-data.frame(rna=r[,gene],protein=p[,gene],group=lab$study$metadata$group);rho<-cor(d$rna,d$protein,use='complete.obs',method='spearman');ggplot(d,aes(rna,protein,color=group,shape=group))+geom_point(size=3,alpha=.85,na.rm=TRUE)+scale_color_manual(values=setNames(c('#287D9E','#BD683C'),lab$study$levels))+scale_shape_manual(values=c(16,17))+labs(title=paste(gene,' |  RNA and protein'),subtitle=sprintf('Same sample IDs and gene ID  |  pooled Spearman rho = %.2f',rho),x=if(is.null(lab$study$units$RNA))'Prepared RNA abundance' else lab$study$units$RNA,y=if(is.null(lab$study$units$Proteomics))'Prepared protein abundance' else lab$study$units$Proteomics)+lab_theme()}
plot_feature_heatmap<-function(lab){meta<-lab$study$metadata;d<-do.call(rbind,lapply(names(lab$prepared),function(name){x<-lab$prepared[[name]]$model[,seq_len(min(12,ncol(lab$prepared[[name]]$model))),drop=FALSE];x<-scale(x,center=TRUE,scale=TRUE);data.frame(sample_id=rep(rownames(x),ncol(x)),feature=rep(colnames(x),each=nrow(x)),value=as.numeric(x),view=name)}));d$group<-factor(meta$group[match(d$sample_id,meta$sample_id)],levels=lab$study$levels);d$sample_id<-factor(d$sample_id,levels=meta$sample_id);d$view<-factor(d$view,levels=names(lab$prepared));ggplot(d,aes(sample_id,feature,fill=pmax(-3,pmin(3,value))))+geom_tile()+facet_grid(view~group,scales='free',space='free')+scale_fill_gradient2(low='#2B7B9D',mid='#FAF8EF',high='#D57750',limits=c(-3,3),na.value='#D5DCDA')+labs(title='Molecular layers, aligned by biological-unit ID',subtitle='First 12 model features  |  within-feature z-scores for display only, capped at +/-3  |  gray = missing',x='Sample',y=NULL,fill='Prepared value')+lab_theme()+theme(axis.text.x=element_blank(),panel.grid=element_blank(),axis.text.y=element_text(size=8),legend.position='right')}
plot_quality<-function(lab){d<-do.call(rbind,lapply(names(lab$prepared),function(name){v<-lab$prepared[[name]];data.frame(sample_id=rownames(v$raw),missing=rowMeans(is.na(v$raw)),view=name,group=lab$study$metadata$group)}));d$sample_id<-factor(d$sample_id,levels=lab$study$metadata$sample_id);ggplot(d,aes(sample_id,missing,fill=group))+geom_col(width=.8)+facet_grid(view~.)+scale_fill_manual(values=setNames(c('#287D9E','#BD683C'),lab$study$levels))+scale_y_continuous(labels=scales::percent,limits=c(0,1))+labs(title='Check missingness before integration',subtitle='Source table missingness before filtering',x='Sample',y='Fraction missing')+lab_theme()+theme(axis.text.x=element_blank(),panel.grid.major.x=element_blank())}
save_lab_figures<-function(lab,mofa,out='outputs'){dir.create(out,recursive=TRUE,showWarnings=FALSE);figures<-list('01_quality'=plot_quality(lab),'02_joint_and_mofa'=plot_integration(lab,mofa),'03_factor_contributions'=plot_factor_contributions(mofa),'04_sample_factor_profiles'=plot_sample_factors(lab,mofa),'05_cross_view_agreement'=plot_view_agreement(lab),'06_rna_protein_example'=plot_gene_pair(lab),'07_aligned_features'=plot_feature_heatmap(lab));for(name in names(figures)){if(!is.null(figures[[name]])){ggsave(file.path(out,paste0(name,'.png')),figures[[name]],width=if(name=='02_joint_and_mofa')12 else 9,height=if(name=='07_aligned_features')8 else 5.5,dpi=220,bg='#FAFCFA');ggsave(file.path(out,paste0(name,'.pdf')),figures[[name]],width=9,height=5.5)}};invisible(figures)}

# Editable PDF and high-resolution PNG from the same R plot.
export_publication <- function(plot, filename, width=7.2, height=5) {
 ggplot2::ggsave(paste0(filename,".pdf"),plot,width=width,height=height,device=grDevices::cairo_pdf,bg="white")
 ggplot2::ggsave(paste0(filename,".png"),plot,width=width,height=height,dpi=600,bg="white")
 if(requireNamespace("svglite",quietly=TRUE))ggplot2::ggsave(paste0(filename,".svg"),plot,width=width,height=height,device=svglite::svglite,bg="white")
}
